CREATE TABLE IF NOT EXISTS users(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(80) UNIQUE NOT NULL,name VARCHAR(100) NOT NULL,password_hash VARCHAR(200) NOT NULL,phone VARCHAR(20) UNIQUE,pin_hash VARCHAR(200),admin BOOLEAN NOT NULL DEFAULT FALSE,active BOOLEAN NOT NULL DEFAULT TRUE,last_read BIGINT UNSIGNED NOT NULL DEFAULT 0,created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3));
CREATE TABLE IF NOT EXISTS sessions(token CHAR(64) PRIMARY KEY,user_id INT UNSIGNED NOT NULL,csrf CHAR(64) NOT NULL,expires_at DATETIME(3) NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS messages(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,parent_id BIGINT UNSIGNED NULL,kind ENUM('text','audio') NOT NULL,body TEXT NOT NULL,media VARCHAR(100),transcript TEXT,transcript_manual BOOLEAN DEFAULT FALSE,version INT NOT NULL DEFAULT 1,yemot_path VARCHAR(200),synced_version INT DEFAULT 0,source ENUM('web','phone') DEFAULT 'web',created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(parent_id) REFERENCES messages(id),INDEX(created_at));
CREATE TABLE IF NOT EXISTS message_versions(message_id BIGINT UNSIGNED NOT NULL,version INT NOT NULL,body TEXT NOT NULL,transcript TEXT,editor_id INT UNSIGNED NOT NULL,created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY(message_id,version),FOREIGN KEY(message_id) REFERENCES messages(id));
CREATE TABLE IF NOT EXISTS jobs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,type ENUM('sync','import','transcribe','push','tzintuk') NOT NULL,message_id BIGINT UNSIGNED NOT NULL,version INT NOT NULL,payload TEXT,state ENUM('pending','running','done','failed','uncertain') DEFAULT 'pending',attempts INT NOT NULL DEFAULT 0,error VARCHAR(200),available_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),UNIQUE(type,message_id,version),INDEX(state,available_at),FOREIGN KEY(message_id) REFERENCES messages(id));
CREATE TABLE IF NOT EXISTS push_subscriptions(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,endpoint_hash CHAR(64) UNIQUE NOT NULL,subscription TEXT NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS auth_attempts(identity CHAR(64) PRIMARY KEY,attempts INT DEFAULT 0,window_start DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3));
CREATE TABLE IF NOT EXISTS phone_reads(user_id INT UNSIGNED NOT NULL,message_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(user_id,message_id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(message_id) REFERENCES messages(id));
